function pointOnPath(progress){let dist=progress, idx=0;while(idx<route.length-1){const a=route[idx],b=route[idx+1],len=Math.hypot(b[0]-a[0],b[1]-a[1])*CELL;if(dist<=len){const t=len?dist/len:0;return{x:(a[0]+(b[0]-a[0])*t+.5)*CELL,y:(a[1]+(b[1]-a[1])*t+.5)*CELL,segment:idx}}dist-=len;idx++}const p=route.at(-1);return{x:(p[0]+.5)*CELL,y:(p[1]+.5)*CELL,segment:route.length-1}}
