function findEditorRoute(){const start=key(...gateStart),goal=key(...gateExit);if(!pathTiles.has(start)||!pathTiles.has(goal))return null;const queue=[gateStart],prev=new Map([[start,null]]);for(let i=0;i<queue.length;i++){const [x,y]=queue[i],k=key(x,y);if(k===goal)break;for(const [nx,ny] of [[x+1,y],[x-1,y],[x,y+1],[x,y-1]]){const nk=key(nx,ny);if(nx>=0&&ny>=0&&nx<COLS&&ny<ROWS&&pathTiles.has(nk)&&!prev.has(nk)){prev.set(nk,k);queue.push([nx,ny])}}}if(!prev.has(goal))return null;const out=[];let at=goal;while(at){out.push(parseKey(at));at=prev.get(at)}return out.reverse()}
